    task.wait(0.25)
    pcall(ev.FeedMosquito.FireServer, ev.FeedMosquito)
    local t0 = os.clock()
    local lastFp, lastMove, lastHp = t.fp, os.clock(), h.Health
    while RUNNING and on("fe_on") and alive() and os.clock() - t0 < budget do
        task.wait(0.4)
        local m = (F.get("Mosquitoes") or {})[t.uid]
        if not m or not m.InBase then break end
        local fp = tonumber(m.FeedProgress) or 0
        if fp >= 0.999 then S.fed = S.fed + 1; break end
        local hh = hum()
        if fp > lastFp + 0.0005 or (hh and hh.Health < lastHp - 1) then lastFp, lastMove = fp, os.clock() end
        if hh then lastHp = hh.Health end
        if os.clock() - lastMove > 5 then
            pcall(ev.StopFeedMosquito.FireServer, ev.StopFeedMosquito)
            F.fire("TakeMosquito", t.uid); task.wait(0.5)
            local sp = F.slot() or p
            F.fire("PlaceMosquito", t.uid, sp); task.wait(0.6)
            F._using = nil
            return
        end
        h = hum()
        if h and h.Health < h.MaxHealth * minHp then
            pcall(ev.StopFeedMosquito.FireServer, ev.StopFeedMosquito)
            if on("fe_reset") then
                task.wait(0.3)
                local c = char()
                pcall(function() hum().Health = 0 end)
                local td = os.clock()
                repeat task.wait(0.2) until (char() ~= c and alive()) or os.clock() - td > 10
                task.wait(0.4)
                F._using = nil
            end
            return
        end
        if on("cb_on") and os.clock() - t0 > 6 and (F.pick()) then break end
        if F.snipeTarget() then break end
    end
    pcall(ev.StopFeedMosquito.FireServer, ev.StopFeedMosquito)
end
function F.brain()
    while RUNNING do
        local ok, err = pcall(function()
            if not alive() then S.task = L["Respawning"]; F._using = nil; task.wait(0.5); return end
            local sn = F.snipeTarget()
            if sn then F.doSnipe(sn); return end
            if on("eg_on") then
                F.hatchReady()
                F.placeHeld()
                F.manageEggs()
            end
            if on("cb_on") then
                local best, full = F.pick()
                if full and (not best or (full.it.step > best.it.step)) and on("cb_heal") then
                    F.heal(full.need)
                    best = F.pick()
                end
                if best then F.fight(best); return end
            end
            if on("fe_on") then
                local list = F.hungry()
                if list[1] then F.feedOne(list[1], on("cb_on") and 12 or 25); return end
            end
            S.task = (on("cb_on") or on("fe_on") or on("eg_on")) and L["Waiting for mamas"] or L["Idle"]
            local hp = F.home()
            local r = hrp()
            if hp and r and (r.Position - hp).Magnitude > 40 and (on("cb_on") or on("fe_on")) then F.goHome() end
            task.wait(0.5)
        end)
        if not ok then S.task = L["Recovering"]; _G.__CW_FAM_LASTERR = err; task.wait(1) end
        task.wait(0.05)
    end
end
function F.incomeLoop()
    pcall(F.fire, "ClaimOfflineIncome")
    while RUNNING do
        if on("in_collect") then F.fire("CollectIncome") end
        if on("in_blood") then F.fire("TransfuseBlood") end
        task.wait(4)
    end
end
function F.shopItems()
    local l = {}
    local coins = F.coins()
    if on("sh_weapon") then
        local cur = F.bestOwned()
        local own = F.owned()
        for _, w in ipairs(F.weapons()) do
            if not own[w.Id] and (w.Damage or 0) > ((cur and cur.Damage) or 0) and (w.CoinCount or 0) > 0 then
                l[#l + 1] = { kind = "weapon", name = w.Name or w.Id, id = w.Id, price = w.CoinCount }
                break
            end
        end
    end
    local function lv(kind, key, cfg, name, remote)
        local L = F.level(key)
        local c = cfg[L]
        if c and c.UpgradePrice and cfg[L + 1] then l[#l + 1] = { kind = kind, name = name .. " " .. (L + 1), price = c.UpgradePrice, remote = remote } end
    end
    if on("sh_base") then lv("base", "BaseLevel", F.BC, L["Base"], "UpgradeBase") end
    if on("sh_blood") then lv("blood", "BloodTransfusionLevel", F.TC, L["Blood"], "UpgradeBloodTransfusion") end
    if on("sh_dmg") then lv("dmg", "DamageLevel", F.DC, L["Damage"], "UpgradeDamage") end
    if on("sh_speed") then lv("speed", "SpeedLevel", F.SPC, L["Speed"], "UpgradeSpeed") end
    if val("sh_order", "Cheapest First") == "Weapons First" then
        table.sort(l, function(a, b) if (a.kind == "weapon") ~= (b.kind == "weapon") then return a.kind == "weapon" end return a.price < b.price end)
    else
        table.sort(l, function(a, b) return a.price < b.price end)
    end
    return l, coins
end
function F.buy(it)
    local c0 = F.coins()
    if it.kind == "weapon" then
        local code = F.invoke("BuyWeapon", it.id)
        task.wait(0.4)
        if code == 200 then F._using = nil; F.invoke("UseWeapon", it.id); F._using = it.id end
    else
        F.fire(it.remote)
        task.wait(0.6)
    end
    if F.coins() < c0 - it.price * 0.5 then S.buys = S.buys + 1; say(L["Bought "] .. it.name); return true end
    F.fail = F.fail or {}
    F.fail[it.name] = os.clock()
    return false
end
function F.shopLoop()
    while RUNNING do
        pcall(function()
            if not on("sh_on") then return end
            local l, coins = F.shopItems()
            for _, it in ipairs(l) do
                if it.price <= coins and not (F.fail and F.fail[it.name] and os.clock() - F.fail[it.name] < 20) then
                    if F.buy(it) then coins = F.coins() end
                end
            end
        end)
        task.wait(0.7)
    end
end
function F.alertsHook()
    track(ACTORS.ChildAdded:Connect(function(x)
        if not RUNNING then return end
        local an = x.Name:match("^Egg_(%a+Area)_Enemy")
        if not an then return end
        local c = F.AC[an]
        if not c then return end
        local now = os.clock()
        if S.snipe[an] and now - S.snipe[an] < 5 then return end
        S.snipe[an] = now
        if on("al_eggs") and (F.RANK[c.Rarity] or 0) >= (F.RANK[val("al_min", "Mythical")] or 6) then notify(c.Rarity .. L[" eggs dropped!"]) end
    end))
end
function F.assistLoop()
    while RUNNING do
        pcall(function()
            if on("cb_on") or not alive() then return end
            local r = hrp()
            if on("as_hit") then
                for _, it in ipairs(F.areas()) do
                    local m, mh, mr = F.mama(it.a, it.c)
                    if m and (mr.Position - r.Position).Magnitude < 6 then
                        local c = char()
                        if c and c:FindFirstChildOfClass("Tool") then for _, a in ipairs(F.tools()) do pcall(a.FireServer, a) end end
                        break
                    end
                end
            end
            if on("as_egg") then
                for _, it in ipairs(F.areas()) do
                    for _, e in ipairs(F.eggsIn(it.a)) do
                        local ok, p = pcall(function() return e.m:GetPivot().Position end)
                        if ok and (p - r.Position).Magnitude < 14 then pcall(function() e.pr.HoldDuration = 0 end); pcall(fireproximityprompt, e.pr) end
                    end
                end
            end
        end)
        task.wait(0.72)
    end
end
function WD.bright(v)
    if v then
        WD.saved = WD.saved or { Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient }
        Lighting.Brightness = 2; Lighting.ClockTime = 14; Lighting.GlobalShadows = false; Lighting.Ambient = Color3.fromRGB(180, 180, 180)
    elseif WD.saved then
        Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient = table.unpack(WD.saved)
        WD.saved = nil
    end
end
function PF.keep(inst, prop, value)
    local s = PF.saved[inst]
    if not s then s = {}; PF.saved[inst] = s end
    if s[prop] == nil then s[prop] = inst[prop] end
    if inst[prop] ~= value then inst[prop] = value end
end
function PF.restore()
    for inst, props in pairs(PF.saved) do for prop, v in pairs(props) do pcall(function() inst[prop] = v end) end end
    PF.saved = {}
end
function PF.world()
    PF.keep(Lighting, "GlobalShadows", false)
    for _, d in ipairs(Lighting:GetChildren()) do
        if d:IsA("PostEffect") then pcall(PF.keep, d, "Enabled", false) end
    end
    local n = 0
    for _, d in ipairs(Workspace:GetDescendants()) do
        n = n + 1
        if n % 2500 == 0 then task.wait() end
        if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") or d:IsA("Smoke") or d:IsA("Fire") or d:IsA("Sparkles") or d:IsA("PointLight") or d:IsA("SpotLight") or d:IsA("SurfaceLight") then
            pcall(PF.keep, d, "Enabled", false)
        elseif d:IsA("BasePart") and d.CastShadow then
            pcall(PF.keep, d, "CastShadow", false)
        end
    end
end
function PF.apply()
    PF.restore()
    local v = on("pf_on")
    pcall(function() settings().Rendering.QualityLevel = v and Enum.QualityLevel.Level01 or Enum.QualityLevel.Automatic end)
    if v then task.spawn(function() pcall(PF.world) end) end
end
