do
    local CAS = game:GetService("ContextActionService")
    local fc = { on = false }
    local Kc = Enum.KeyCode
    local keys = { Kc.W, Kc.A, Kc.S, Kc.D, Kc.Q, Kc.E, Kc.Space, Kc.LeftShift, Kc.Up, Kc.Down, Kc.Left, Kc.Right }
    local function stop()
        if not fc.on then return end
        fc.on = false
        pcall(function() CAS:UnbindAction("CW_Freecam") end)
        pcall(function() UserInputService.MouseBehavior = Enum.MouseBehavior.Default end)
        local cam = Workspace.CurrentCamera
        if cam then
            cam.CameraType = Enum.CameraType.Custom
            local h = hum(); if h then cam.CameraSubject = h end
        end
    end
    local function start()
        local cam = Workspace.CurrentCamera
        if not cam then return end
        fc.on = true
        fc.pos = cam.CFrame.Position
        local rx, ry = cam.CFrame:ToEulerAnglesYXZ()
        fc.pitch, fc.yaw = rx, ry
        cam.CameraType = Enum.CameraType.Scriptable
        pcall(function() CAS:BindActionAtPriority("CW_Freecam", function() return Enum.ContextActionResult.Sink end, false, Enum.ContextActionPriority.High.Value + 100, table.unpack(keys)) end)
    end
    local fkey = HttpService:GenerateGUID(false)
    RunService:BindToRenderStep(fkey, Enum.RenderPriority.Last.Value, function(dt)
        if not (RUNNING and on("wd_freecam")) then stop(); return end
        if not fc.on then start() end
        local cam = Workspace.CurrentCamera
        if not cam then return end
        cam.CameraType = Enum.CameraType.Scriptable
        if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
            local d = UserInputService:GetMouseDelta()
            fc.yaw = fc.yaw - d.X * 0.005
            fc.pitch = math.clamp(fc.pitch - d.Y * 0.005, -1.5, 1.5)
        elseif UserInputService.MouseBehavior == Enum.MouseBehavior.LockCurrentPosition then
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        end
        local mv = Vector3.zero
        if not UserInputService:GetFocusedTextBox() then
            local function k(a, b) return UserInputService:IsKeyDown(a) or (b and UserInputService:IsKeyDown(b)) end
            if k(Kc.W, Kc.Up) then mv = mv + Vector3.new(0, 0, -1) end
            if k(Kc.S, Kc.Down) then mv = mv + Vector3.new(0, 0, 1) end
            if k(Kc.A, Kc.Left) then mv = mv + Vector3.new(-1, 0, 0) end
            if k(Kc.D, Kc.Right) then mv = mv + Vector3.new(1, 0, 0) end
            if k(Kc.E, Kc.Space) then mv = mv + Vector3.new(0, 1, 0) end
            if k(Kc.Q) then mv = mv + Vector3.new(0, -1, 0) end
        end
        local rot = CFrame.fromEulerAnglesYXZ(fc.pitch, fc.yaw, 0)
        local spd = val("wd_fcspeed", 40) * (UserInputService:IsKeyDown(Kc.LeftShift) and 3 or 1)
        if mv.Magnitude > 0 then fc.pos = fc.pos + rot:VectorToWorldSpace(mv.Unit) * spd * (dt or 0.016) end
        cam.CFrame = CFrame.new(fc.pos) * rot
    end)
    onClean(function() pcall(function() RunService:UnbindFromRenderStep(fkey) end); stop() end)
end
do
    local MS = game:GetService("MarketplaceService")
    _G.__FAM_HOOK = { MS = MS, block = function() return RUNNING and on("pr_robux") end }
    onClean(function() if _G.__FAM_HOOK then _G.__FAM_HOOK.block = function() return false end end end)
    if hookmetamethod and not _G.__FAM_HOOKED then
        local blockM = { PromptProductPurchase = true, PromptGamePassPurchase = true, PromptPurchase = true, PromptBundlePurchase = true, PromptSubscriptionPurchase = true }
        local old
        old = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            local H = _G.__FAM_HOOK
            if H and not checkcaller() and self == H.MS and blockM[getnamecallmethod()] and H.block() then return nil end
            return old(self, ...)
        end))
        _G.__FAM_HOOKED = true
    end
    local hid = false
    local function promptApp() local ok, cg = pcall(function() return game:GetService("CoreGui") end); return ok and cg and cg:FindFirstChild("PurchasePromptApp") end
    task.spawn(function()
        while RUNNING do
            local app = promptApp()
            if app then
                if on("pr_robux") then
                    if app.Enabled then pcall(function() app.Enabled = false end); hid = true end
                elseif hid then
                    pcall(function() app.Enabled = true end); hid = false
                end
            end
            task.wait(0.2)
        end
    end)
    onClean(function() local app = promptApp(); if app and hid then pcall(function() app.Enabled = true end) end end)
end
